-- Recurring consent over bounded explicit product UUIDs; same native rule/087 writer.
CREATE TABLE public.product_rule_schedule_previews(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES public.tenants,actor_id uuid NOT NULL REFERENCES public.users,client_key uuid NOT NULL,request_hash text NOT NULL,scope_hash text NOT NULL,schedule_id uuid NOT NULL,expected_version integer NOT NULL,settings jsonb NOT NULL,run_id uuid NOT NULL,commit_key uuid,commit_result jsonb,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),expires_at timestamptz NOT NULL DEFAULT clock_timestamp()+interval '15 minutes',UNIQUE(tenant_id,id),UNIQUE(tenant_id,client_key),FOREIGN KEY(tenant_id,run_id) REFERENCES public.product_rule_runs(tenant_id,id));
CREATE TABLE public.product_rule_schedules(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES public.tenants,version integer NOT NULL CHECK(version>0),settings jsonb NOT NULL,rules jsonb NOT NULL,approved_by uuid NOT NULL REFERENCES public.users,preview_id uuid NOT NULL,enabled boolean NOT NULL,next_at timestamptz,error text,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,preview_id) REFERENCES public.product_rule_schedule_previews(tenant_id,id));
CREATE INDEX product_rule_schedule_due ON public.product_rule_schedules(next_at,id) WHERE enabled;
CREATE TABLE public.product_rule_schedule_occurrences(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,schedule_id uuid NOT NULL,schedule_version integer NOT NULL,approved_by uuid NOT NULL REFERENCES public.users,client_key uuid NOT NULL,due_at timestamptz NOT NULL,run_id uuid NOT NULL,settings jsonb NOT NULL,rules jsonb NOT NULL,scope_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,client_key),UNIQUE(tenant_id,run_id),UNIQUE(tenant_id,schedule_id,schedule_version,due_at),FOREIGN KEY(tenant_id,schedule_id) REFERENCES public.product_rule_schedules(tenant_id,id),FOREIGN KEY(tenant_id,run_id) REFERENCES public.product_rule_runs(tenant_id,id));
DO $$DECLARE n text;BEGIN FOREACH n IN ARRAY ARRAY['product_rule_schedule_previews','product_rule_schedules','product_rule_schedule_occurrences'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',n);EXECUTE format('ALTER TABLE public.%I FORCE ROW LEVEL SECURITY',n);EXECUTE format($policy$CREATE POLICY tenant_scope ON public.%I TO dyna_app USING(tenant_id=(SELECT nullif(current_setting('app.tenant_id',true),'')::uuid)) WITH CHECK(tenant_id=(SELECT nullif(current_setting('app.tenant_id',true),'')::uuid))$policy$,n);EXECUTE format('GRANT SELECT,INSERT ON public.%I TO dyna_app',n);END LOOP;END $$;
GRANT UPDATE ON public.product_rule_schedules,public.product_rule_schedule_previews TO dyna_app;
CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON public.product_rule_schedule_occurrences FOR EACH ROW EXECUTE FUNCTION public.price_bulk_edit_immutable();
CREATE FUNCTION public.product_rule_schedule_preview_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$BEGIN IF TG_OP='DELETE' OR OLD.commit_result IS NOT NULL OR (to_jsonb(NEW)-ARRAY['commit_key','commit_result']) IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['commit_key','commit_result']) OR NEW.commit_key IS NULL OR NEW.commit_result IS NULL THEN RAISE EXCEPTION 'Schedule preview is immutable' USING ERRCODE='23514';END IF;RETURN NEW;END $$;
CREATE TRIGGER preview_immutable BEFORE UPDATE OR DELETE ON public.product_rule_schedule_previews FOR EACH ROW EXECUTE FUNCTION public.product_rule_schedule_preview_guard();
CREATE FUNCTION public.product_rule_schedule_config_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE p record;r record;BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Schedule has durable occurrences' USING ERRCODE='23514';END IF;
 IF TG_OP='UPDATE' THEN
  IF ROW(NEW.id,NEW.tenant_id,NEW.created_at) IS DISTINCT FROM ROW(OLD.id,OLD.tenant_id,OLD.created_at) THEN RAISE EXCEPTION 'Schedule identity immutable' USING ERRCODE='23514';END IF;
  IF NEW.version=OLD.version AND ROW(NEW.settings,NEW.rules,NEW.approved_by,NEW.preview_id,NEW.enabled) IS NOT DISTINCT FROM ROW(OLD.settings,OLD.rules,OLD.approved_by,OLD.preview_id,OLD.enabled) THEN RETURN NEW;END IF;
  IF NEW.version<>OLD.version+1 THEN RAISE EXCEPTION 'Schedule requires next version' USING ERRCODE='23514';END IF;
  IF NOT NEW.enabled AND ROW(NEW.settings,NEW.rules,NEW.approved_by,NEW.preview_id) IS NOT DISTINCT FROM ROW(OLD.settings,OLD.rules,OLD.approved_by,OLD.preview_id) THEN RETURN NEW;END IF;
 END IF;
 SELECT * INTO p FROM public.product_rule_schedule_previews WHERE(tenant_id,id)=(NEW.tenant_id,NEW.preview_id);SELECT * INTO r FROM public.product_rule_runs WHERE(tenant_id,id)=(NEW.tenant_id,p.run_id);
 IF p.id IS NULL OR p.commit_result IS NOT NULL OR(NEW.id,NEW.settings,NEW.rules,NEW.approved_by) IS DISTINCT FROM(p.schedule_id,p.settings,r.rules,p.actor_id) OR NEW.version<>p.expected_version+1 OR(TG_OP='INSERT' AND p.expected_version<>0) OR NOT NEW.enabled THEN RAISE EXCEPTION 'Schedule has no own preview consent' USING ERRCODE='23514';END IF;RETURN NEW;
END $$;
CREATE TRIGGER config_guard BEFORE INSERT OR UPDATE OR DELETE ON public.product_rule_schedules FOR EACH ROW EXECUTE FUNCTION public.product_rule_schedule_config_guard();
CREATE FUNCTION public.product_rule_schedule_pin(rid uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;o record;s record;r record;role text;BEGIN
 SELECT * INTO o FROM public.product_rule_schedule_occurrences WHERE(tenant_id,run_id)=(t,rid);IF o.id IS NULL THEN RETURN;END IF;
 IF NOT public.product_rule_schedule_guards() THEN RAISE EXCEPTION 'Schedule schema incomplete' USING ERRCODE='55000';END IF;
 SELECT * INTO s FROM public.product_rule_schedules WHERE(tenant_id,id)=(t,o.schedule_id) FOR SHARE;SELECT * INTO r FROM public.product_rule_runs WHERE(tenant_id,id)=(t,rid);
 IF s.id IS NULL OR NOT s.enabled OR(s.version,s.settings,s.rules,s.approved_by) IS DISTINCT FROM(o.schedule_version,o.settings,o.rules,o.approved_by) OR r.origin IS DISTINCT FROM 'manual' OR r.queued_actor IS DISTINCT FROM o.approved_by OR r.actor_id IS DISTINCT FROM o.approved_by OR r.scope_hash IS DISTINCT FROM o.scope_hash OR r.rules IS DISTINCT FROM o.rules OR NOT(r.state IN('queued','done')) OR r.consent IS DISTINCT FROM jsonb_build_object('confirmed',true,'scope_hash',r.scope_hash)
 OR(SELECT array_agg(product_id ORDER BY product_id) FROM public.product_rule_items WHERE(tenant_id,run_id)=(t,rid)) IS DISTINCT FROM(SELECT array_agg(x::uuid ORDER BY x::uuid) FROM jsonb_array_elements_text(o.settings->'product_ids')x) THEN RAISE EXCEPTION 'Schedule scope changed' USING ERRCODE='23514';END IF;
 SELECT m.role INTO role FROM public.memberships m WHERE(m.tenant_id,m.user_id)=(t,o.approved_by) FOR SHARE;IF role IS DISTINCT FROM 'admin' THEN RAISE EXCEPTION 'Schedule owner revoked' USING ERRCODE='42501';END IF;
END $$;
CREATE FUNCTION public.product_rule_schedule_binding() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$BEGIN PERFORM public.product_rule_schedule_pin(NEW.run_id);RETURN NULL;END $$;
CREATE CONSTRAINT TRIGGER schedule_binding AFTER INSERT ON public.product_rule_schedule_occurrences DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.product_rule_schedule_binding();
CREATE TABLE public.product_rule_schedule_manifest(id boolean PRIMARY KEY DEFAULT true CHECK(id),fingerprint text NOT NULL);
REVOKE ALL ON public.product_rule_schedule_manifest FROM PUBLIC,dyna_app;
CREATE FUNCTION public.product_rule_schedule_fingerprint() RETURNS text LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
 SELECT md5(jsonb_build_object(
 'tables',(SELECT jsonb_agg(jsonb_build_object('name',c.relname,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force',c.relforcerowsecurity,
 'acl',(SELECT jsonb_agg(jsonb_build_array(pg_get_userbyid(a.grantor),CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type,a.is_grantable) ORDER BY CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee)::text END,a.privilege_type,pg_get_userbyid(a.grantor)::text,a.is_grantable) FROM aclexplode(coalesce(c.relacl,acldefault('r',c.relowner)))a),
 'cols',(SELECT jsonb_agg(jsonb_build_array(x.attname,format_type(x.atttypid,x.atttypmod),x.attnotnull,(SELECT jsonb_agg(jsonb_build_array(pg_get_userbyid(ca.grantor),CASE WHEN ca.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(ca.grantee)::text END,ca.privilege_type,ca.is_grantable) ORDER BY CASE WHEN ca.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(ca.grantee)::text END,ca.privilege_type,pg_get_userbyid(ca.grantor)::text,ca.is_grantable) FROM aclexplode(x.attacl)ca),pg_get_expr(d.adbin,d.adrelid)) ORDER BY x.attnum) FROM pg_attribute x LEFT JOIN pg_attrdef d ON(d.adrelid,d.adnum)=(x.attrelid,x.attnum) WHERE x.attrelid=c.oid AND x.attnum>0 AND NOT x.attisdropped),
 'constraints',(SELECT jsonb_agg(pg_get_constraintdef(k.oid,true) ORDER BY k.conname) FROM pg_constraint k WHERE k.conrelid=c.oid),
 'policies',(SELECT jsonb_agg(jsonb_build_array(po.polname,(SELECT array_agg(CASE WHEN x=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x)::text END ORDER BY CASE WHEN x=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x)::text END) FROM unnest(po.polroles)x),po.polcmd,pg_get_expr(po.polqual,po.polrelid),pg_get_expr(po.polwithcheck,po.polrelid)) ORDER BY po.polname) FROM pg_policy po WHERE po.polrelid=c.oid),
 'triggers',(SELECT jsonb_agg(jsonb_build_array(tr.tgname,tr.tgenabled,pg_get_triggerdef(tr.oid,true)) ORDER BY tr.tgname) FROM pg_trigger tr WHERE tr.tgrelid=c.oid AND NOT tr.tgisinternal)) ORDER BY c.relname) FROM pg_class c WHERE c.relnamespace='public'::regnamespace AND c.relname IN('product_rule_schedule_previews','product_rule_schedules','product_rule_schedule_occurrences','product_rule_schedule_manifest')),
 'functions',(SELECT jsonb_agg(jsonb_build_array(p.oid::regprocedure::text,pg_get_functiondef(p.oid),pg_get_userbyid(p.proowner),(SELECT jsonb_agg(jsonb_build_array(pg_get_userbyid(a.grantor),CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type,a.is_grantable) ORDER BY CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee)::text END,a.privilege_type,pg_get_userbyid(a.grantor)::text,a.is_grantable) FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner)))a)) ORDER BY p.oid::regprocedure::text) FROM pg_proc p WHERE p.pronamespace='public'::regnamespace AND p.proname IN('product_rule_schedule_preview_guard','product_rule_schedule_config_guard','product_rule_schedule_binding','product_rule_schedule_guards','product_rule_schedule_pin','product_rule_schedule_fingerprint','price_bulk_edit_immutable'))
 )::text) $$;

CREATE FUNCTION public.product_rule_schedule_guards() RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE signature text;n text;BEGIN
 FOREACH n IN ARRAY ARRAY['product_rule_schedule_previews','product_rule_schedules','product_rule_schedule_occurrences','product_rule_schedule_manifest'] LOOP IF to_regclass('public.'||n) IS NULL THEN RETURN false;END IF;END LOOP;
 FOREACH signature IN ARRAY ARRAY['public.product_rule_schedule_pin(uuid)','public.product_rule_schedule_binding()','public.product_rule_schedule_preview_guard()','public.product_rule_schedule_config_guard()','public.product_rule_schedule_fingerprint()','public.product_rule_price_tags_guards()'] LOOP IF to_regprocedure(signature) IS NULL THEN RETURN false;END IF;END LOOP;
 RETURN public.product_rule_price_tags_guards() AND(SELECT fingerprint=public.product_rule_schedule_fingerprint() FROM public.product_rule_schedule_manifest WHERE id);
END $$;
REVOKE ALL ON FUNCTION public.product_rule_schedule_fingerprint(),public.product_rule_schedule_binding(),public.product_rule_schedule_config_guard() FROM PUBLIC,dyna_app;
REVOKE ALL ON FUNCTION public.product_rule_schedule_pin(uuid),public.product_rule_schedule_guards(),public.product_rule_schedule_preview_guard() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.product_rule_schedule_pin(uuid),public.product_rule_schedule_guards() TO dyna_app;
INSERT INTO public.product_rule_schedule_manifest VALUES(true,public.product_rule_schedule_fingerprint());
